def largest_subset(numbers):
    """
    Find the size of the largest subset where every pair is divisible.
    A pair (a, b) is divisible if a % b == 0 or b % a == 0.
    """
    if not numbers:
        return 0

    numbers = sorted(set(numbers))  # Remove duplicates and sort
    n = len(numbers)

    # dp[i] = size of largest subset where numbers[i] is the maximum element
    dp = [1] * n

    for i in range(n):
        for j in range(i):
            # Check if numbers[i] is divisible by numbers[j]
            if numbers[i] % numbers[j] == 0:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)
