    def sum_of_proper_divisors(n):
        if n <= 1:
            return 0
        divisor_sum = 1  # 1 is always a proper divisor for n > 1
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                divisor_sum += i
                if i != n // i:  # avoid counting the square root twice
                    divisor_sum += n // i
        return divisor_sum

