def tuple_intersection(list1, list2):
    """
    Find the tuple intersection of elements in the given tuple lists irrespective of their order.
    Tuples are considered equal if they contain the same elements in any order.
    """
    # Normalize tuples by sorting them so (3, 4) and (4, 3) are treated as the same
    def normalize(tup):
        return tuple(sorted(tup))

    # Create sets of normalized tuples from both lists
    set1 = {normalize(t) for t in list1}
    set2 = {normalize(t) for t in list2}

    # Return the intersection
    return set1 & set2
