def check_expression(expression):
    """
    Check if the given expression has balanced brackets/parentheses.

    Args:
        expression: A string containing brackets, parentheses, and braces

    Returns:
        True if the expression is balanced, False otherwise
    """
    stack = []
    matching_brackets = {')': '(', '}': '{', ']': '['}

    for char in expression:
        if char in '({[':
            stack.append(char)
        elif char in ')}]':
            if not stack or stack[-1] != matching_brackets[char]:
                return False
            stack.pop()

    return len(stack) == 0
