def cal_sum(n):
    """
    Write a function to calculate the sum of perrin numbers.
    assert cal_sum(9) == 49
    """
    if n < 0:
        return 0

    # Initialize the first three Perrin numbers
    perrin = [3, 0, 2]

    # If n is within the initial three, sum up to index n
    if n < 3:
        return sum(perrin[:n+1])

    # Generate Perrin numbers up to index n
    for i in range(3, n + 1):
        next_perrin = perrin[i-2] + perrin[i-3]
        perrin.append(next_perrin)

    # Return the sum of the first n+1 terms (indices 0 to n)
    return sum(perrin[:n+1])
